const userId = $json.jwtPayload?.userId;
if (!userId) return [{ json: { __error: true, __code: 401, __message: 'Token sin userId' } }];
const b = $json.body || {};
const orderId = (b.order_id || '').toString().trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(orderId)) return [{ json: { __error: true, __code: 400, __message: 'order_id es requerido' } }];
const action = (b.action || '').toString().trim();
if (!['follow', 'unfollow', 'add', 'remove'].includes(action)) {
  return [{ json: { __error: true, __code: 400, __message: 'action debe ser follow, unfollow, add o remove' } }];
}
const target = (b.user_id || '').toString().trim();
if ((action === 'add' || action === 'remove') && !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(target)) {
  return [{ json: { __error: true, __code: 400, __message: 'user_id es requerido' } }];
}
return [{ json: { user_id: String(userId), payload: JSON.stringify({ order_id: orderId, action, user_id: target }) } }];

// Arma el sobre { code, message, data, meta }. Un resultado vacío en una
// operación de escritura significa que el WHERE de guarda no dejó pasar:
// es un 409/404, no un 500.
//
// El filtro descarta el item vacio que emite el nodo de Postgres cuando la
// consulta no devuelve filas (lleva alwaysOutputData para que el flujo llegue a
// responder). Sin el, ese {} se colaria como si fuera una fila real: un detalle
// de orden vacio en vez de un 404, o un listado con un elemento fantasma.
const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);

if (!rows.length || !rows[0].order_id) {
  return [{ json: { __error: true, __code: 409,
    __message: 'No se pudieron cambiar los seguidores: sin permiso, sin acceso a la orden o usuario no válido' } }];
}
const MESSAGES = { follow: 'Ahora seguís la orden', unfollow: 'Dejaste de seguir la orden', add: 'Seguidor agregado', remove: 'Seguidor quitado' };
return [{ json: { __data: { followers: rows[0].followers ?? [], is_following: rows[0].is_following === true }, __message: MESSAGES[rows[0].action] || 'OK' } }];
